<script setup lang="ts">
import { computed, ref, watch } from "vue";
import { listResources, listServiceAccessGrants, listServiceIdentities, listServiceTechnicalRoles, requestServiceAccess, requestServiceTechnicalRoleAccess } from "../api";
import type { Resource, ServiceAccessGrant, ServiceIdentity, ServiceTechnicalRole } from "../api/contracts";
import Alert from "../components/Alert.vue";
import DataPanel from "../components/DataPanel.vue";
import Icon from "../components/Icon.vue";
import ServiceNavigation from "../components/ServiceNavigation.vue";
import { useCatalogsStore } from "../stores/catalogs";

const catalogs = useCatalogsStore();
const consumerId = ref(""), identityId = ref(""), targetId = ref("");
const accessType = ref<"resource" | "role">("resource"), resourceId = ref(""), technicalRoleId = ref("");
const identities = ref<ServiceIdentity[]>([]), resources = ref<Resource[]>([]), technicalRoles = ref<ServiceTechnicalRole[]>([]), grants = ref<ServiceAccessGrant[]>([]);
const busy = ref(false), error = ref("");
const otherApps = computed(() => catalogs.apps.filter((app) => app.id !== consumerId.value));
const selectedIdentity = computed(() => identities.value.find((item) => item.id === identityId.value));
async function loadIdentities() { identities.value = []; identityId.value = ""; grants.value = []; if (consumerId.value) try { identities.value = (await listServiceIdentities(consumerId.value)).data; } catch (cause) { error.value = cause instanceof Error ? cause.message : "No fue posible consultar las identidades."; } }
async function loadResources() { resources.value = []; technicalRoles.value = []; resourceId.value = ""; technicalRoleId.value = ""; if (targetId.value) try { const [listedResources, listedRoles] = await Promise.all([listResources(targetId.value), listServiceTechnicalRoles(targetId.value, { page: 0, size: 100 })]); resources.value = listedResources.data; technicalRoles.value = listedRoles.data.content; } catch (cause) { error.value = cause instanceof Error ? cause.message : "No fue posible consultar los recursos."; } }
async function loadGrants() { grants.value = []; if (consumerId.value && identityId.value) try { grants.value = (await listServiceAccessGrants(consumerId.value, identityId.value)).data; } catch (cause) { error.value = cause instanceof Error ? cause.message : "No fue posible consultar las solicitudes."; } }
async function submit() { if (!consumerId.value || !identityId.value || (accessType.value === "resource" && !resourceId.value) || (accessType.value === "role" && !technicalRoleId.value)) return; busy.value = true; try { if (accessType.value === "role") await requestServiceTechnicalRoleAccess(consumerId.value, identityId.value, technicalRoleId.value); else await requestServiceAccess(consumerId.value, identityId.value, resourceId.value); await loadGrants(); resourceId.value = ""; technicalRoleId.value = ""; } catch (cause) { error.value = cause instanceof Error ? cause.message : "No fue posible enviar la solicitud."; } finally { busy.value = false; } }
watch(consumerId, loadIdentities); watch(targetId, loadResources); watch(identityId, loadGrants);
</script>

<template><div class="access-page"><Alert v-if="error" type="error" :message="error" @close="error=''"/><ServiceNavigation /><div class="request-grid"><DataPanel title="Nueva solicitud" :count="0" empty="" :show-content-when-empty="true" :eyebrow="null"><form class="request-form" @submit.prevent="submit"><label>Aplicación consumidora<select v-model="consumerId"><option value="">Selecciona una aplicación</option><option v-for="app in catalogs.apps" :key="app.id" :value="app.id">{{ app.name }}</option></select></label><label>Identidad de servicio<select v-model="identityId" :disabled="!consumerId"><option value="">Selecciona una identidad</option><option v-for="identity in identities" :key="identity.id" :value="identity.id">{{ identity.name }}</option></select></label><label>Aplicación dueña del acceso<select v-model="targetId" :disabled="!identityId"><option value="">Selecciona una aplicación</option><option v-for="app in otherApps" :key="app.id" :value="app.id">{{ app.name }}</option></select></label><label>Tipo de solicitud<select v-model="accessType" :disabled="!targetId"><option value="resource">Recurso específico · SERVICE_CONSUMER</option><option value="role">Rol técnico agrupado</option></select></label><label v-if="accessType === 'resource'">Recurso protegido<select v-model="resourceId" :disabled="!targetId"><option value="">Selecciona un recurso</option><option v-for="resource in resources" :key="resource.id" :value="resource.id">{{ resource.method }} {{ resource.path }}</option></select></label><label v-else>Rol técnico<select v-model="technicalRoleId" :disabled="!targetId"><option value="">Selecciona un rol técnico</option><option v-for="role in technicalRoles" :key="role.id" :value="role.id">{{ role.name }} · {{ role.code }}</option></select></label><button class="create-action" :disabled="busy || (accessType === 'resource' ? !resourceId : !technicalRoleId)"><Icon name="arrow" :size="15" />{{ busy ? "Enviando…" : "Enviar solicitud" }}</button></form></DataPanel><DataPanel title="Contexto de la solicitud" :count="0" empty="" :show-content-when-empty="true" :eyebrow="null"><div class="request-context"><span><Icon name="key" :size="18" /></span><strong>{{ selectedIdentity?.name ?? "Elige una identidad" }}</strong><p>Un recurso específico recibe automáticamente <code>SERVICE_CONSUMER</code>. Un rol técnico concede sólo los recursos agrupados en el rol y sólo a esta identidad.</p></div></DataPanel></div><DataPanel title="Solicitudes de esta identidad" :count="grants.length" empty="" :show-content-when-empty="true" :eyebrow="null"><div v-if="grants.length" class="request-list"><article v-for="grant in grants" :key="grant.id"><strong>{{ grant.resourceId ? resources.find((resource) => resource.id === grant.resourceId)?.path ?? "Recurso protegido" : `Rol técnico ${grant.technicalRole}` }}</strong><span>{{ grant.technicalRole }} · {{ grant.status === "PENDING" ? "Pendiente" : grant.status === "APPROVED" ? "Aprobada" : grant.status }}</span></article></div><p v-else class="empty-note">Selecciona una identidad para ver sus solicitudes y su estado.</p></DataPanel></div></template>

<style scoped>
.access-page{display:grid;gap:20px}.request-grid{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(280px,.75fr);gap:18px}.request-form{display:grid;gap:16px;padding:0 26px 26px}.request-form label{display:grid;gap:7px;color:var(--text);font-size:12px;font-weight:600}.request-form select,.request-form input{height:38px;border:1px solid var(--line);border-radius:6px;background:#fff;padding:0 10px;color:var(--ink)}.create-action{justify-self:start;height:36px;border:0;border-radius:6px;padding:0 13px;background:var(--ink);color:#fff;display:inline-flex;align-items:center;gap:7px;font-size:12px;font-weight:600}.request-context{display:grid;gap:10px;padding:0 26px 26px}.request-context span{display:grid;place-items:center;width:36px;height:36px;border-radius:7px;color:var(--green-ink);background:var(--green-wash)}.request-context strong{font-size:14px}.request-context p,.empty-note{margin:0;color:var(--text);font-size:13px;line-height:1.5}.request-list{border-top:1px solid var(--soft-line)}.request-list article{display:grid;gap:4px;padding:14px 26px;border-top:1px solid var(--soft-line);font-size:13px}.request-list span{color:var(--text);font-size:12px}.empty-note{padding:24px 26px}@media(max-width:760px){.request-grid{grid-template-columns:1fr}}
</style>
